import json
from dataclasses import dataclass, field
from typing import Any, Dict, Optional, Type

@dataclass
class MyModel:
    name: str
    age: int
    email: Optional[str] = field(default=None)

def parse_and_validate(json_str: str, model_class: Type) -> Any:
    """
    Parses a JSON string and validates it against a given dataclass model.

    Args:
        json_str (str): JSON string to parse.
        model_class (Type): A dataclass representing the expected structure.

    Returns:
        Any: An instance of the model_class if valid.

    Raises:
        ValueError: If JSON is invalid or data does not match the model.
    """
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format")

    for field_name, field in model_class.__dataclass_fields__.items():
        field_type = field.type

        if field.default is dataclasses.MISSING and field.default_factory is None:
            # Required field
            if field_name not in data:
                raise ValueError(f"Missing required field: {field_name}")
            if not isinstance(data[field_name], field_type):
                raise ValueError(
                    f"Field '{field_name}' has incorrect type: expected {field_type}, got {type(data[field_name])}"
                )
        elif field.default is not dataclasses.MISSING:
            # Optional field (has a default value)
            if field_name in data:
                if not isinstance(data[field_name], field_type):
                    raise ValueError(
                        f"Field '{field_name}' has incorrect type: expected {field_type}, got {type(data[field_name])}"
                    )
    return model_class(**data)

