def get_env_value(key, default=None):
    """
    Retrieve the value of the specified key from a .env file.

    If the key is not found, or the file does not exist, the default value is returned.
    """
    try:
        with open('.env', 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    k, v = line.split('=', 1)
                    k = k.strip()
                    if k == key:
                        return v.strip()
    except FileNotFoundError:
        pass
    return default

import os

def get_env_value(key, default):
    env_path = '.env'
    if not os.path.exists(env_path):
        return default

    env_vars = {}
    with open(env_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' in line:
                k, v = line.split('=', 1)
                env_vars[k.strip()] = v.strip()

    return env_vars.get(key, default)

