# In-memory user storage for demo (replace with a proper database in production)
users_db = {}

class UserRegister(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

def hash_password(password: str) -> str:
    """Hash a password using bcrypt and return a base64-encoded string."""
    hashed = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
    return base64.b64encode(hashed).decode('utf-8')

def verify_password(plain_password: str, hashed_password: str) -> bool:
    """Verify a plain password against a bcrypt hash using base64 decoding."""
    hash_bytes = base64.b64decode(hashed_password)
    return bcrypt.checkpw(plain_password.encode('utf-8'), hash_bytes)

app = FastAPI()

@app.post("/auth/register")
def register_user(user: UserRegister):
    if user.username in users_db:
        raise HTTPException(status_code=400, detail="Username already exists")

    hashed_password = hash_password(user.password)
    users_db[user.username] = hashed_password

    return {"message": "User registered successfully"}

