def login_user(user: UserLogin):
    if user.username not in users_db:
        raise HTTPException(status_code=401, detail="User not found")

    stored_hash = users_db[user.username]
    if verify_password(user.password, stored_hash):
        return {"token": "example_token"}
    else:
        raise HTTPException(status_code=401, detail="Invalid password")

import phonenumbers

def format_phone_number(input_str, country_code):
    # Remove all non-digit characters
    digits = ''.join(filter(str.isdigit, input_str))

    # Check for empty number
    if not digits:
        return 'Invalid number'

    try:
        # Parse the number with country code
        num = phonenumbers.parse(digits, country_code)

        # Validate the number
        if phonenumbers.is_valid_number(num):
            # Format the number into international (E.164) format
            return phonenumbers.format_number(num, phonenumbers.PhoneNumberFormat.INTERNATIONAL)
        else:
            return 'Invalid number'
    except phonenumbers.NumberParseException:
        return 'Invalid number'

