import time
from functools import wraps

def cache_result(ttl: int):
    cache = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Generate cache key
            key = f"{func.__module__}.{func.__name__}:{args}:{kwargs}"

            now = time.time()
            if key in cache:
                stored_time, result = cache[key]
                if now - stored_time < ttl:
                    return result

            # If cache is expired or not present, compute and cache
            result = func(*args, **kwargs)
            cache[key] = (now, result)
            return result

        return wrapper

    return decorator

